def make_handler(store: Store) -> type[BaseHTTPRequestHandler]:
    class Handler(BaseHTTPRequestHandler):
        server_version = "PersistentKV/1.0"

        def log_message(self, format: str, *args: Any) -> None:
            logging.info("%s - %s", self.address_string(), format % args)

        def _respond(self, status: int, payload: Any | None = None) -> None:
            self.send_response(status)
            if payload is not None:
                encoded = json.dumps(payload, ensure_ascii=False, separators=(",", ":"), allow_nan=False).encode("utf-8")
                self.send_header("Content-Type", "application/json")
                self.send_header("Content-Length", str(len(encoded)))
            else:
                encoded = b""
                self.send_header("Content-Length", "0")
            self.end_headers()
            if encoded:
                self.wfile.write(encoded)

        def _error(self, status: int, message: str) -> None:
            self._respond(status, {"error": message})

        def _key(self) -> str | None:
            raw_path = urlsplit(self.path).path
            prefix = "/v1/kv/"
            if not raw_path.startswith(prefix):
                return None
            raw_key = raw_path[len(prefix):]
            if not raw_key or "/" in raw_key:
                return None
            try:
                key = unquote_to_bytes(raw_key).decode("utf-8")
            except UnicodeDecodeError:
                return None
            return key if key and "/" not in key else None

        def _read_json(self) -> Any:
            length_header = self.headers.get("Content-Length")
            if length_header is None:
                raise ValueError("Content-Length is required")
            try:
                length = int(length_header)
            except ValueError as exc:
                raise ValueError("invalid Content-Length") from exc
            if length < 0 or length > MAX_BODY:
                raise OverflowError("request body exceeds 1 MiB")
            try:
                return json.loads(self.rfile.read(length).decode("utf-8"))
            except (UnicodeDecodeError, json.JSONDecodeError) as exc:
                raise ValueError("malformed JSON") from exc

        def do_GET(self) -> None:
            path = urlsplit(self.path).path
            if path == "/health":
                self._respond(200, {"status": "ok"})
            elif path == "/v1/keys":
                self._respond(200, {"keys": store.keys()})
            else:
                key = self._key()
                if key is None:
                    self._error(404, "unknown route")
                    return
                found, value = store.get(key)
                if not found:
                    self._error(404, "key not found")
                else:
                    self._respond(200, {"key": key, "value": value})

        def do_PUT(self) -> None:
            key = self._key()
            if key is None:
                self._error(404, "unknown route")
                return
            try:
                body = self._read_json()
                if not isinstance(body, dict) or "value" not in body or set(body) - {"value", "ttl_seconds"}:
                    raise ValueError("body must be an object with value and optional ttl_seconds")
                ttl = body.get("ttl_seconds")
                if ttl is not None and (isinstance(ttl, bool) or not isinstance(ttl, (int, float))
                                        or not math.isfinite(ttl) or ttl <= 0):
                    raise ValueError("ttl_seconds must be a finite number greater than zero")
                json.dumps(body["value"], allow_nan=False)
            except OverflowError as exc:
                self._error(413, str(exc))
                return
            except (TypeError, ValueError) as exc:
                self._error(400, str(exc))
                return
            try:
                created = store.put(key, body["value"], ttl)
            except (OSError, TypeError, ValueError) as exc:
                logging.exception("failed to persist update")
                self._error(500, "could not persist data")
                return
            self._respond(201 if created else 200, {"key": key, "value": body["value"]})

        def do_DELETE(self) -> None:
            key = self._key()
            if key is None:
                self._error(404, "unknown route")
            elif store.delete(key):
                self._respond(204)
            else:
                self._error(404, "key not found")

        def do_POST(self) -> None: self._error(405, "method not allowed")
        def do_PATCH(self) -> None: self._error(405, "method not allowed")
        def do_HEAD(self) -> None: self._error(405, "method not allowed")

    return Handler


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--host", required=True)
    parser.add_argument("--port", required=True, type=int)
    parser.add_argument("--data", required=True, type=Path)
    args = parser.parse_args()
    logging.basicConfig(level=logging.INFO, format="%(asctime)s %(levelname)s %(message)s")
    store = Store(args.data)
    httpd = ThreadingHTTPServer((args.host, args.port), make_handler(store))
    httpd.daemon_threads = True

    def stop(_signum: int, _frame: Any) -> None:
        logging.info("SIGTERM received; shutting down")
        threading.Thread(target=httpd.shutdown, daemon=True).start()

    signal.signal(signal.SIGTERM, stop)
    print(f"LISTENING {httpd.server_address[1]}", flush=True)
    try:
        httpd.serve_forever()
    finally:
        store.save()
        httpd.server_close()


if __name__ == "__main__":
    main()
import http.client
import json
import os
import subprocess
import sys
import tempfile
import time
import unittest
from pathlib import Path
from urllib.parse import quote


ROOT = Path(__file__).parent


class ServerTests(unittest.TestCase):
    def setUp(self):
        self.temp = tempfile.TemporaryDirectory()
        self.data = Path(self.temp.name) / "data.json"
        self.start()

    def tearDown(self):
        self.proc.terminate()
        self.proc.wait(timeout=5)
        self.temp.cleanup()

    def start(self):
        self.proc = subprocess.Popen([sys.executable, "server.py", "--host", "127.0.0.1", "--port", "0", "--data", str(self.data)], cwd=ROOT, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)
        line = self.proc.stdout.readline().strip()
        self.assertRegex(line, r"^LISTENING [1-9][0-9]*$")
        self.port = int(line.split()[1])

    def request(self, method, path, body=None):
        conn = http.client.HTTPConnection("127.0.0.1", self.port, timeout=3)
        encoded = None if body is None else json.dumps(body).encode()
        conn.request(method, path, body=encoded, headers={} if encoded is None else {"Content-Type": "application/json"})
        response = conn.getresponse()
        raw = response.read()
        conn.close()
        return response.status, json.loads(raw) if raw else None

    def test_crud_unicode_ttl_and_restart(self):
        key = quote("hello world", safe="")
        self.assertEqual(self.request("PUT", "/v1/kv/" + key, {"value": {"n": 1}})[0], 201)
        self.assertEqual(self.request("PUT", "/v1/kv/" + key, {"value": None})[0], 200)
        self.assertEqual(self.request("GET", "/v1/kv/" + key), (200, {"key": "hello world", "value": None}))
        self.assertEqual(self.request("GET", "/v1/keys"), (200, {"keys": ["hello world"]}))
        self.assertEqual(self.request("PUT", "/v1/kv/short", {"value": 1, "ttl_seconds": .05})[0], 201)
        time.sleep(.08)
        self.assertEqual(self.request("GET", "/v1/kv/short")[0], 404)
        self.proc.terminate(); self.proc.wait(timeout=5)
        self.start()
        self.assertEqual(self.request("GET", "/v1/kv/" + key)[1]["value"], None)
        self.assertEqual(self.request("DELETE", "/v1/kv/" + key)[0], 204)

    def test_errors(self):
        self.assertEqual(self.request("GET", "/nope")[0], 404)
        self.assertEqual(self.request("POST", "/health")[0], 405)
        self.assertEqual(self.request("PUT", "/v1/kv/x", {"ttl_seconds": 1})[0], 400)
        self.assertEqual(self.request("PUT", "/v1/kv/x", {"value": 1, "ttl_seconds": 0})[0], 400)


if __name__ == "__main__":
    unittest.main()
# Persistent HTTP key-value service

Dependency-free Python 3.11+ JSON key-value server with atomic on-disk persistence and optional per-value TTLs.

Run it with:

```sh
python3 server.py --host 127.0.0.1 --port 0 --data ./kv-data.json
```

The first stdout line reports `LISTENING <port>`. Diagnostics are written to stderr.

The API offers `PUT`, `GET`, and `DELETE /v1/kv/{url-encoded-key}`, `GET /v1/keys`, and `GET /health`. PUT accepts `{"value": any-json, "ttl_seconds": positive-number}`. Entries are atomically persisted to the data path and expired entries are removed.

Run the integration tests:

```sh
python3 -m unittest -v test_server.py
```

